run(): void {
  this.port.on("message", (value: unknown) => {
    if (
      typeof value === "object" &&
      value !== null &&
      "kind" in value &&
      value.kind === "output-ack"
    ) {
      try {
        const request = DaemonNavigationWorkerProtocol.request(value);
        if (request.kind !== "output-ack") throw new Error("Invalid output acknowledgement");
        this.acknowledgeOutput(request.requestId, request.sequence);
        return;
      } catch (error) {
        this.fail("protocol", error);
        return;
      }
    }
    this.tail = this.tail.then(() => this.handle(value));
  });
}

private async releaseTransientResources(operationId: string): Promise<void> {
  try {
    await Promise.all(
      this.retainedProgram?.backends.map((backend) => backend.releaseTransientResources()) ?? [],
    );
    const heap = getHeapStatistics();
    this.send({
      kind: "heap",
      generation: this.data.generation,
      operationId,
      usedHeapBytes: heap.used_heap_size,
      heapLimitBytes: heap.heap_size_limit,
    });
  } catch (error) {
    this.fail("resource", error, { operationId });
  }
}

private async receive(value: unknown): Promise<void> {
  let response: DaemonNavigationWorkerResponse;
  try {
    response = DaemonNavigationWorkerProtocol.response(value);
  } catch (error) {
    this.failCommunication(error);
    return;
  }
  if (response.generation !== this.generation) return;
  if (response.kind === "output-chunk") {
    await this.receiveOutputChunk(response);
    return;
  }
  const key = NodeDaemonNavigationWorker.responseKey(response);
  if (this.completed.has(key)) {
    this.failCommunication(new Error(`Duplicate daemon navigation worker response: ${key}`));
    return;
  }
  const pending = this.pending.get(key);
  if (pending === undefined) {
    this.failCommunication(new Error(`Uncorrelated daemon navigation worker response: ${key}`));
    return;
  }
  this.pending.delete(key);
  this.completed.add(key);
  if (response.kind === "failed") {
    pending.reject(new Error(`Daemon navigation worker ${response.failureCode} failure`));
    return;
  }
  if (response.kind === "closed") this.closeAcknowledged = true;
  pending.resolve(response);
}

private async releaseTransientResources(): Promise<void> {
  const generation = this.workerGeneration;
  if (generation === undefined) return;
  const response = await generation.worker.releaseTransientResources();
  if (response.kind !== "heap") throw new Error("Navigation worker did not report heap usage");
  this.resourceSupervisor.workerHeapReported(
    response.generation,
    response.usedHeapBytes,
    response.heapLimitBytes,
  );
  this.operationObserver.worker({
    kind: "resources-released",
    workerGeneration: response.generation,
    workerHeapUsedBytes: response.usedHeapBytes,
    workerHeapLimitBytes: response.heapLimitBytes,
  });
}

private observeWorkerExit(
  exit: import("./daemon-navigation-worker.js").DaemonNavigationWorkerExit,
): void {
  if (this.shutdownStarted) return;
  this.logger.record({
    kind: "failure",
    operation: "worker-exit",
    failureCode: "worker-exit",
    errorName: DaemonLogger.errorName(
      exit.errorName === undefined ? undefined : { name: exit.errorName },
    ),
  });
  const recovery = this.resourceSupervisor.workerExited(exit);
  this.workerRecoveryOperation = recovery;
  void recovery.catch((error) => {
    this.logger.record({
      kind: "failure",
      operation: "worker-replacement",
      failureCode: "controlled-resource",
      errorName: DaemonLogger.errorName(error),
    });
  });
}

private async shed(
  runAtBoundary: (operation: () => Promise<void>) => Promise<void>,
): Promise<void> {
  if (this.shedOperation !== undefined) return this.shedOperation;
  const operation = runAtBoundary(async () => {
    try {
      await this.options.releaseTransientResources();
      this.shedCompleted = true;
    } catch (error) {
      await this.replace("shed-failure");
      throw error;
    }
  });
  this.shedOperation = operation;
  try {
    await operation;
  } finally {
    if (this.shedOperation === operation) this.shedOperation = undefined;
  }
}

async workerExited(exit: import("./daemon-navigation-worker.js").DaemonNavigationWorkerExit) {
  if (exit.generation !== this.currentGeneration || this.currentState === "stopped") return;
  await this.replace(exit.cause === "out-of-memory" ? "out-of-memory" : "worker-exit");
}

it("preserves the current turn when backend refresh fails", async () => {
  const failure = new Error("refresh failure");
  let refreshFails = false;
  const state = {
    refresh: vi.fn(() => {
      if (refreshFails) return Promise.reject(failure);
      return Promise.resolve({ added: 0, changed: 0, removed: 0, unchanged: 0 });
    }),
    ensureFiles: vi.fn(() => Promise.resolve()),
    locate: vi.fn(() => []),
  } as unknown as TypeScriptWorkspaceState;
  let definitionSearches = 0;
  const backend = new TypeScriptBackend(new InMemoryFileSystem({}), state, undefined, {
    definitionSearch: () => {
      definitionSearches += 1;
    },
  });
  const snapshot: WorkspaceSnapshot = { root: "/repo", files: [] };
  const target = identity("src/app.ts", "target");
  await backend.refresh({ snapshot, coverage: "workspace" });
  const definitions = await backend.findDefinitions([], target);
  refreshFails = true;

  await expect(backend.refresh({ snapshot, coverage: "workspace" })).rejects.toBe(failure);

  await expect(backend.findDefinitions([], target)).resolves.toBe(definitions);
  expect(definitionSearches).toBe(1);
});

it("clears caches before awaiting project release and rejects at the backend boundary", async () => {
  const releaseFailure = new Error("project release failed");
  let rejectProjectRelease: ((reason: unknown) => void) | undefined;
  const projectRelease = new Promise<void>((_resolve, reject) => {
    rejectProjectRelease = reject;
  });
  void projectRelease.catch(() => undefined);
  const firstProjectRelease = vi.fn(() => projectRelease);
  const laterProjectRelease = vi.fn();
  const projectGraph = {
    releaseTransientResources: vi.fn(async () => {
      await firstProjectRelease();
      laterProjectRelease();
    }),
  } as unknown as TypeScriptProjectGraph;
  const state = {
    refresh: vi.fn(() => Promise.resolve({ added: 0, changed: 0, removed: 0, unchanged: 0 })),
    ensureFiles: vi.fn(() => Promise.resolve()),
    locate: vi.fn(() => []),
  } as unknown as TypeScriptWorkspaceState;
  let definitionSearches = 0;
  const backend = new TypeScriptBackend(new InMemoryFileSystem({}), state, projectGraph, {
    definitionSearch: () => {
      definitionSearches += 1;
    },
  });
  const snapshot: WorkspaceSnapshot = { root: "/repo", files: [] };
  const target = identity("src/app.ts", "target");
  await backend.refresh({ snapshot, coverage: "selection" });
  const beforeRelease = await backend.findDefinitions([], target);

  const release = backend.releaseTransientResources();
  let releaseSettled = false;
  void release.then(
    () => {
      releaseSettled = true;
    },
    () => {
      releaseSettled = true;
    },
  );
  const afterRelease = await backend.findDefinitions([], target);

  expect(afterRelease).not.toBe(beforeRelease);
  expect(definitionSearches).toBe(2);
  expect(projectGraph.releaseTransientResources).toHaveBeenCalledOnce();
  await Promise.resolve();
  expect(releaseSettled).toBe(false);

  rejectProjectRelease?.(releaseFailure);
  await expect(release).rejects.toBe(releaseFailure);
  expect(firstProjectRelease).toHaveBeenCalledOnce();
  expect(laterProjectRelease).not.toHaveBeenCalled();
});

